        }

        var $f = $(f);

        if(typeof f.token === "undefined")
            $f.prepend('<input type="hidden" name="token" value="">');

        $f.find("input[name=token]").val(token);

        return true;
    });
});

(function(){
    var openBtns = document.querySelectorAll('[data-modal]');
    var policyReturnFocus = null;
    function openModal(id){
        var m = document.getElementById(id);
        if(!m) return;
        policyReturnFocus = document.activeElement;
        m.classList.add('is-open');
        m.setAttribute('aria-hidden','false');
        m.querySelector('.policy-modal-x').focus();
        document.body.classList.add('policy-modal-open');
    }
    function closeAll(){
        document.querySelectorAll('.policy-modal.is-open').forEach(function(m){ m.classList.remove('is-open'); m.setAttribute('aria-hidden','true'); });
        document.body.classList.remove('policy-modal-open');
        if(policyReturnFocus){ policyReturnFocus.focus(); policyReturnFocus=null; }
    }
    openBtns.forEach(function(btn){
        btn.addEventListener('click', function(e){
            e.preventDefault();
            openModal(btn.getAttribute('data-modal'));
        });
    });
    document.querySelectorAll('.policy-modal [data-close]').forEach(function(el){
        el.addEventListener('click', closeAll);
    });
    document.addEventListener('keydown', function(e){
        var modal=document.querySelector('.policy-modal.is-open');
        if(!modal) return;
        if(e.key === 'Escape') closeAll();
        if(e.key === 'Tab') {
            var items=modal.querySelectorAll('button,a[href]'), first=items[0], last=items[items.length-1];
            if(e.shiftKey && document.activeElement===first){ e.preventDefault(); last.focus(); }
            else if(!e.shiftKey && document.activeElement===last){ e.preventDefault(); first.focus(); }
        }
    });

    // 맨 위로 버튼
    var totop = document.getElementById('totop');
    if(totop){
        totop.addEventListener('click', function(){
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
    }
})();

