    var existing = config && config.getAttribute('data-existing') === '1';
    var id = 'G-FCNVVSL24W', optKey = 'twinh_analytics_optout';
    var optedOut = false, sent = Object.create(null);
    try { optedOut = w.localStorage.getItem(optKey) === '1'; } catch (_) {}
    w['ga-disable-' + id] = optedOut;
    w.dataLayer = w.dataLayer || [];
    function command() { w.dataLayer.push(arguments); }
    if (enabled && !optedOut && !existing && !d.querySelector('script[src*="gtm.js?id=GTM-WHDKTJGF"]')) {
        w.dataLayer.push({'gtm.start': Date.now(), event: 'gtm.js'});
        var tag = d.createElement('script');
        tag.async = true;
        tag.src = 'https://www.googletagmanager.com/gtm.js?id=GTM-WHDKTJGF';
        d.head.appendChild(tag);
    }
    w.twinhContactConversion = function (receipt) {
        if (!enabled || optedOut || !/^[a-f0-9]{32}$/.test(receipt) || sent[receipt]) return false;
        var key = 'twinh_contact_sent_' + receipt;
        try { if (w.sessionStorage.getItem(key)) return false; } catch (_) {}
        sent[receipt] = true;
        try { w.sessionStorage.setItem(key, '1'); } catch (_) {}
        // GTM에 게시된 contact_submit 태그 하나만 사용한다. Ads 직접 전환과 중복 전송하지 않는다.
        w.dataLayer.push({event: 'contact_submit'});
        return true;
    };
    function updateButton() {
        d.querySelectorAll('[data-analytics-toggle]').forEach(function (button) {
            button.textContent = optedOut ? '방문 통계 수집 허용' : '방문 통계 수집 거부';
            button.setAttribute('aria-pressed', optedOut ? 'true' : 'false');
        });
    }
    d.addEventListener('DOMContentLoaded', updateButton);
    d.addEventListener('click', function (event) {
        var button = event.target.closest('[data-analytics-toggle]');
        if (button) {
            optedOut = !optedOut;
            w['ga-disable-' + id] = optedOut;
            try { w.localStorage.setItem(optKey, optedOut ? '1' : '0'); } catch (_) {}
            updateButton();
            if (!optedOut) w.location.reload();
            return;
        }
        if (!enabled || optedOut) return;
        var link = event.target.closest('a[href]');
        if (!link) return;
        var href = link.getAttribute('href') || '', name = '';
        if (/^tel:/i.test(href)) name = 'click_phone';
        else if (/^mailto:/i.test(href)) name = 'click_email';
        else if (/^https:\/\/pf\.kakao\.com\//i.test(href)) name = 'click_kakao';
        // 보조 행동은 주요 문의 전환과 구별한다. 링크 주소/전화번호/이메일은 매개변수에 넣지 않는다.
        if (name) command('event', name, {send_to: id});
    });
})(window, document);

// ===== TWIN H Main Script =====
document.addEventListener('DOMContentLoaded', function () {
    // clients marquee
    const c1 = ['기업', '공공기관', '축제', '교육기관', '스타트업'];
    const c2 = ['ENTERPRISE', 'PUBLIC', 'FESTIVAL', 'EDUCATION', 'STARTUP'];

    function buildMarq(id, arr, outline) {
        let h = '';
        for (let k = 0; k < 2; k++) {
            arr.forEach((t, i) => {
                h += '<span class="' + ((i % 2 === (outline ? 0 : 1)) ? 'o' : '') + '">' + t + '</span><span class="dot"></span>';
            });
        }
        var el = document.getElementById(id);
        if (el) el.innerHTML = h;
    }
    buildMarq('cmq1', c1, false);
    buildMarq('cmq2', c2, true);

    // scroll
    let last = 0;
    const hdr = document.getElementById('hdr');
    const prog = document.getElementById('prog');
    const totop = document.getElementById('totop');
    const onScrollSub = () => {
        const s = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0,
            d = document.body.scrollHeight - innerHeight;
        if (prog) prog.style.width = (s / d * 100) + '%';
        if (hdr) hdr.classList.toggle('solid', s > 60);
        const isDesktop = window.innerWidth > 1000; // 모바일에서는 헤더(메뉴)를 숨기지 않음
        if (hdr) hdr.style.transform = (s > last && s > 500 && isDesktop) ? 'translateY(-100%)' : '';
        last = s;
        if (totop) totop.classList.toggle('on', s > 700);
    };
    addEventListener('scroll', onScrollSub, { passive: true });
    // 일부 모바일 환경에서 스크롤이 window가 아닌 요소에서 일어나도 동작하도록 보강
    document.addEventListener('scroll', onScrollSub, { capture: true, passive: true });
    if (totop) totop.onclick = () => scrollTo({
        top: 0,
        behavior: 'smooth'
    });

    // process step 활성화 (스크롤 진입 시 번호 채움)
    const pio = new IntersectionObserver(es => {
        es.forEach(e => {
            e.target.classList.toggle('act', e.isIntersecting);
        });
    }, {
        threshold: .5
    });
    document.querySelectorAll('.proc-item').forEach(el => pio.observe(el));

    // counters
    function animc(el) {
        const t = +el.dataset.count,
            suf = el.dataset.suf || '';
        let c = 0;
        const step = t / 60;
        const tick = () => {
            c += step;
            if (c < t) {
                el.textContent = Math.floor(c).toLocaleString() + suf;
                requestAnimationFrame(tick);
            } else el.textContent = t.toLocaleString() + suf;
        };
        tick();
    }
    const cio = new IntersectionObserver(es => {
        es.forEach(e => {
            if (e.isIntersecting) animc(e.target);
        });
    }, {
        threshold: .6
    });
    document.querySelectorAll('[data-count]').forEach(el => cio.observe(el));
});

/* TWINH: confirmed enquiries, explicit matching consent and non-PII funnel events. */
(function (w, d) {
    'use strict';
    var config = d.currentScript;
    var enabled = config && config.getAttribute('data-enabled') === '1';
    var pixelId = config && config.getAttribute('data-pixel-id');
    var host = w.location.hostname.toLowerCase();
    var consentBlocked = false, sent = Object.create(null), funnelSent = Object.create(null);
    var optKey = 'twinh_analytics_optout';
    function optedOut() {
        try { return consentBlocked || w.localStorage.getItem(optKey) === '1'; }
        catch (_) { return consentBlocked; }
    }
    function syncChoice() {
        d.cookie = optKey + '=' + (optedOut() ? '1' : '0') + '; Path=/; Max-Age=31536000; SameSite=Lax; Secure';
    }
    if (!enabled || !pixelId || (host !== 'twinh.co.kr' && host !== 'www.twinh.co.kr')) return;
    syncChoice();
    if (optedOut()) return;
    if (w.twinhOpenAIContactConversion || w.oaiq || d.querySelector('script[src*="bzrcdn.openai.com/sdk/oaiq.min.js"]')) return;
    var command = function () { command.q.push(arguments); };
    command.q = [];
    w.oaiq = command;

    function eventId(prefix) {
        if (w.crypto && typeof w.crypto.randomUUID === 'function') return prefix + w.crypto.randomUUID();
        return prefix + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2);
    }
    function cookie(name) {
        var parts = d.cookie.split(';');
        for (var i = 0; i < parts.length; i++) {
            var value = parts[i].trim();
            if (value.indexOf(name + '=') === 0) {
                try { return decodeURIComponent(value.slice(name.length + 1)); } catch (_) { return ''; }
            }
        }
        return '';
    }
    function opaque(value) { return typeof value === 'string' && value.length <= 4096 && !/[\x00-\x20\x7f]/.test(value) ? value : ''; }
    w.twinhOpenAIContext = function () {
        if (optedOut()) return {enabled:false};
        var landing = '';
        try { landing = new URLSearchParams(w.location.search).get('oppref') || ''; } catch (_) {}
        return {enabled:true, oppref:opaque(landing || cookie('__oppref')), obref:opaque(cookie('__obref'))};
    };
    w.twinhOpenAIFunnel = function (name) {
        var allowed = ['contact_form_started','contact_submit_attempt','contact_submit_error','contact_phone_clicked','contact_email_clicked'];
        if (optedOut() || allowed.indexOf(name) < 0 || funnelSent[name]) return false;
        try {
            w.oaiq('measure', 'custom', {type:'custom'}, {custom_event_name:name, event_id:eventId('twinh_funnel_'), opt_out:true});
            funnelSent[name] = true;
            return true;
        } catch (_) { return false; }
    };
    w.twinhOpenAIContactConversion = function (receipt, metadata) {
        if (optedOut() || typeof receipt !== 'string' || !/^[a-f0-9]{32}$/.test(receipt) || sent[receipt]) return false;
        var key = 'twinh_openai_lead_' + receipt;
        try { if (w.sessionStorage.getItem(key)) return false; } catch (_) {}
        try {
            var user = {}, provided = metadata && metadata.user;
            ['email_sha256','phone_number_sha256'].forEach(function (field) {
                if (provided && typeof provided[field] === 'string' && /^[a-f0-9]{64}$/.test(provided[field])) user[field] = provided[field];
            });
            if (Object.keys(user).length) w.oaiq('init', {pixelId:pixelId, user:user});
            var id = metadata && metadata.event_id;
            if (typeof id !== 'string' || !/^twinh_lead_[a-f0-9]{64}$/.test(id)) id = eventId('twinh_lead_');
            w.oaiq('measure', 'lead_created', {type:'customer_action'}, {event_id:id, opt_out:true});
            sent[receipt] = true;
            try { w.sessionStorage.setItem(key, '1'); } catch (_) {}
            return true;
        } catch (_) { return false; }
    };
    d.addEventListener('click', function (event) {
        var target = event.target;
        if (!target || typeof target.closest !== 'function') return;
        var button = target.closest('[data-analytics-toggle]');
        if (button) {
            consentBlocked = !optedOut();
            try { w.localStorage.setItem(optKey, consentBlocked ? '1' : '0'); } catch (_) {}
            syncChoice();
            button.setAttribute('aria-pressed', consentBlocked ? 'true' : 'false');
            button.textContent = consentBlocked ? '방문 통계 수집 허용' : '방문 통계 수집 거부';
            w.oaiq('consent', !consentBlocked);
            return;
        }
        var link = target.closest('a[href]');
        var href = link && link.getAttribute('href') || '';
        if (/^tel:/i.test(href)) w.twinhOpenAIFunnel('contact_phone_clicked');
        if (/^mailto:/i.test(href)) w.twinhOpenAIFunnel('contact_email_clicked');
    }, true);
    d.addEventListener('input', function (event) {
        var target = event.target;
        if (target && typeof target.closest === 'function' && target.closest('#projForm') && target.id !== 'website') w.twinhOpenAIFunnel('contact_form_started');
    }, true);
    w.addEventListener('storage', function (event) {
        if (event.key !== optKey) return;
        consentBlocked = event.newValue === '1'; syncChoice();
        w.oaiq('consent', !optedOut());
    });
    var sdk = d.createElement('script'); sdk.async = true;
    sdk.src = 'https://bzrcdn.openai.com/sdk/oaiq.min.js'; d.head.appendChild(sdk);
    try { if (w.localStorage.getItem(optKey) === '0') w.oaiq('consent', true); } catch (_) {}
    w.oaiq('init', {pixelId:pixelId});
    w.oaiq('measure', 'page_viewed', {type:'contents'}, {event_id:eventId('twinh_page_'), opt_out:true});
})(window, document);

var wrestMsg = "";
var wrestFld = null;
var wrestFldDefaultColor = "";
//var wrestFldBackColor = "#ff3061";

// subject 속성값을 얻어 return, 없으면 tag의 name을 넘김
function wrestItemname(fld)
{
    //return fld.getAttribute("title") ? fld.getAttribute("title") : ( fld.getAttribute("alt") ? fld.getAttribute("alt") : fld.name );
    var id = fld.getAttribute("id");
    var labels = document.getElementsByTagName("label");
    var el = null;

    for(i=0; i<labels.length; i++) {
        if(id == labels[i].htmlFor) {
            el = labels[i];
            break;
        }
    }

    if(el != null) {
        var text =  el.innerHTML.replace(/[<].*[>].*[<]\/+.*[>]/gi, "");

        if(text == '') {
            return fld.getAttribute("title") ? fld.getAttribute("title") : ( fld.getAttribute("placeholder") ? fld.getAttribute("placeholder") : fld.name );
        } else {
            return text;
        }
    } else {
        return fld.getAttribute("title") ? fld.getAttribute("title") : ( fld.getAttribute("placeholder") ? fld.getAttribute("placeholder") : fld.name );
    }
}

// 양쪽 공백 없애기
function wrestTrim(fld)
{
    var pattern = /(^\s+)|(\s+$)/g; // \s 공백 문자
    return fld.value.replace(pattern, "");
}

// 필수 입력 검사
function wrestRequired(fld)
{
    if (wrestTrim(fld) == "") {
        if (wrestFld == null) {
            // 셀렉트박스일 경우에도 필수 선택 검사합니다.
            wrestMsg = wrestItemname(fld) + " : 필수 "+(fld.type=="select-one"?"선택":"입력")+"입니다.\n";
            wrestFld = fld;
        }
    }
}

// 김선용 2006.3 - 전화번호(휴대폰) 형식 검사 : 123-123(4)-5678
function wrestTelNum(fld)
{
    if (!wrestTrim(fld)) return;

    var pattern = /^[0-9]{2,3}-[0-9]{3,4}-[0-9]{4}$/;
    if(!pattern.test(fld.value)){
        if(wrestFld == null){
            wrestMsg = wrestItemname(fld)+" : 전화번호 형식이 올바르지 않습니다.\n\n하이픈(-)을 포함하여 입력하세요.\n";
            wrestFld = fld;
            fld.select();
        }
    }
}

// 이메일주소 형식 검사
