document.addEventListener('DOMContentLoaded', function () {
    var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var circleVideoSrc = g5_url + '/image/main/hero_movie.mp4?v=3';

    // 준비 중인 포트폴리오: 메인·목록·그리드에서 같은 안내를 표시한다.
    (function () {
        var modal = document.getElementById('portfolioPendingDialog');
        if (!modal) return;
        var project = document.getElementById('portfolioPendingProject');
        var confirm = modal.querySelector('.pf-pending-confirm');
        var returnFocus = null, background = [], previousOverflow = null;

        function closePending() {
            if (modal.hidden) return;
            modal.hidden = true;
            background.forEach(function (item) {
                if (!item.inert) item.el.removeAttribute('inert');
            });
            background = [];
            document.body.style.overflow = previousOverflow.body;
            document.documentElement.style.overflow = previousOverflow.html;
            if (returnFocus && returnFocus.isConnected) returnFocus.focus({ preventScroll: true });
        }
        document.addEventListener('click', function (event) {
            var trigger = event.target.closest('[data-portfolio-pending]');
            if (!trigger || !modal.hidden) return;
            event.preventDefault();
            returnFocus = trigger;
            project.textContent = trigger.getAttribute('data-project-title') || '';
            previousOverflow = { body: document.body.style.overflow, html: document.documentElement.style.overflow };
            modal.hidden = false;
            confirm.focus({ preventScroll: true });
            Array.prototype.forEach.call(document.body.children, function (el) {
                if (el === modal || /^(SCRIPT|STYLE|LINK|META)$/.test(el.tagName)) return;
                background.push({ el: el, inert: el.hasAttribute('inert') });
                el.setAttribute('inert', '');
            });
            document.body.style.overflow = 'hidden';
            document.documentElement.style.overflow = 'hidden';
        });
        modal.querySelectorAll('[data-pending-close]').forEach(function (button) {
            button.addEventListener('click', closePending);
        });
        document.addEventListener('keydown', function (event) {
            if (modal.hidden) return;
            if (event.key === 'Escape') {
                event.preventDefault();
                closePending();
            }
            if (event.key === 'Tab') {
                var buttons = modal.querySelectorAll('button');
                var first = buttons[0], last = buttons[buttons.length - 1];
                if (event.shiftKey && document.activeElement === first) {
                    event.preventDefault(); last.focus();
                } else if (!event.shiftKey && document.activeElement === last) {
                    event.preventDefault(); first.focus();
                }
            }
        });
    })();


    // marquee
    (function () {
        var bmq = document.getElementById('bmq');
        if (bmq) {
            var bh = '';
            for (var k = 0; k < 2; k++) {
                bh += '<span>Powered by Tech,</span><span class="o">Driven by Sense.</span>';
            }
            bmq.innerHTML = bh;
        }
    })();

    // hero text animation
    (function () {
        var hero = document.querySelector('.hero');
        if (!hero) return;
        var hio = new IntersectionObserver(function (es) {
            es.forEach(function (e) {
                if (e.isIntersecting) {
                    if (!hero.classList.contains('play')) {
                        requestAnimationFrame(function () { hero.classList.add('play'); });
                    }
                } else {
                    hero.classList.remove('play');
                }
            });
        }, { threshold: .35 });
        hio.observe(hero);
    })();

    // hero video: keep the poster image as the first LCP paint, then attach video after the page starts.
    (function () {
        var video = document.querySelector('.hs-media .hero-video[data-src]');
        if (!video) return;
        var desktop = window.matchMedia('(min-width: 769px)');
        // 데이터 절약·모션 감소 환경에서는 포스터를 유지한다. 모바일 영상은 공통 배경에서 재생한다.
        var connection = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
        if (reduceMotion ||
            (connection && (connection.saveData || /(^|-)2g$/.test(connection.effectiveType || '')))) return;
        function playHeroVideo() {
            if (!desktop.matches) return;
            var playback = video.play();
            if (playback && playback.catch) playback.catch(function () {});
        }
        function loadHeroVideo() {
            if (!desktop.matches) {
                video.pause();
                return;
            }
            if (video.dataset.loaded) {
                playHeroVideo();
                return;
            }
            video.dataset.loaded = '1';
            var source = document.createElement('source');
            source.src = circleVideoSrc;
            source.type = 'video/mp4';
            video.appendChild(source);
            video.muted = true;
            video.playsInline = true;
            video.addEventListener('playing', function () {
                if (!desktop.matches) {
                    video.pause();
                    return;
                }
                var media = video.parentNode;
                if (media) media.classList.add('video-ready');
            });
            video.load();
            if (video.readyState >= 2) playHeroVideo();
            else video.addEventListener('loadeddata', playHeroVideo, { once: true });
        }
        window.addEventListener('load', function () {
            setTimeout(loadHeroVideo, 900);
        }, { once: true });
        if (desktop.addEventListener) desktop.addEventListener('change', loadHeroVideo);
        else desktop.addListener(loadHeroVideo);
    })();

    // Mobile circle backgrounds share the project page's size and the main video.
    (function () {
        var mobile = window.matchMedia('(max-width: 768px)');
        var connection = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
        var saveData = connection && (connection.saveData || /(^|-)2g$/.test(connection.effectiveType || ''));
        var observer = 'IntersectionObserver' in window ? new IntersectionObserver(function (entries) {
            entries.forEach(function (entry) {
                var video = entry.target.querySelector('.tw-circle-video');
                if (entry.isIntersecting) playCircle(video);
                else video.pause();
            });
        }, { rootMargin: '200px 0px' }) : null;

        function playCircle(video) {
            if (reduceMotion || saveData) return;
            if (!video.dataset.loaded) {
                video.dataset.loaded = '1';
                video.src = circleVideoSrc;
            }
            var playback = video.play();
            if (playback && playback.catch) playback.catch(function () {});
        }

        function setupCircles() {
            if (!mobile.matches) return;
            document.querySelectorAll('.hs-media, .chero-bg, .shero-bg, .pj-page, .faq-page, .contact-page, .f-cta').forEach(function (target) {
                var media = target.querySelector('.tw-circle-media');
                if (media && media.dataset.circleBound) return;
                if (!media) {
                    media = document.createElement('div');
                    media.className = 'tw-circle-media';
                    media.setAttribute('aria-hidden', 'true');
                    target.insertBefore(media, target.firstChild);
                }
                var video = media.querySelector('.tw-circle-video');
                if (!video) {
                    video = document.createElement('video');
                    video.className = 'tw-circle-video';
                    media.appendChild(video);
                }
                media.dataset.circleBound = '1';
                video.muted = true;
                video.autoplay = true;
                video.loop = true;
                video.playsInline = true;
                video.setAttribute('muted', '');
                video.setAttribute('playsinline', '');
                video.preload = 'none';
                video.tabIndex = -1;
                video.addEventListener('playing', function () { media.classList.add('video-ready'); });
                video.addEventListener('error', function () { media.classList.remove('video-ready'); });
                if (observer) observer.observe(media);
                else playCircle(video);
            });
        }
        setupCircles();
        if (mobile.addEventListener) mobile.addEventListener('change', setupCircles);
        else mobile.addListener(setupCircles);
    })();

    // scroll
    (function () {
        var last = 0;
        var hdr = document.getElementById('hdr');
        var prog = document.getElementById('prog');
        var inqFloat = document.getElementById('inqFloat');
        var kakaoFloat = document.getElementById('kakaoFloat');
        var totop = document.getElementById('totop');
        var wk = document.getElementById('works');
        var st = document.getElementById('strength');
        var veil = document.getElementById('hsVeil');
        var ticking = false;

        function getScrollTop() {
            // 그누보드 환경에서 스크롤 컨테이너가 window가 아닐 수 있어 안전하게 처리
            return window.pageYOffset ||
                document.documentElement.scrollTop ||
                document.body.scrollTop || 0;
        }

        function render(full) {
            ticking = false;
            var winW = window.innerWidth;
            var pageX = window.pageXOffset || document.documentElement.scrollLeft || document.body.scrollLeft || 0;
            var s = getScrollTop();
            var vh = window.innerHeight;
            var ov = document.getElementById('overlay');
            var ovOpen = !!(ov && ov.classList.contains('on'));
            var isDesktop = winW > 1000; // 모바일에서는 헤더(메뉴)를 숨기지 않음
            var d = 0;
            var workProgress = null;
            var strengthProgress = null;

            if (full) {
                d = document.documentElement.scrollHeight - vh;

                if (wk) {
                    var wr = wk.getBoundingClientRect();
                    workProgress = (vh - wr.top) / (vh * 0.7);
                    workProgress = Math.max(0, Math.min(1, workProgress));
                }

                if (st) {
                    var r = st.getBoundingClientRect();
                    var range = st.offsetHeight - vh; // r.height 대신 offsetHeight 사용(안정)
                    strengthProgress = range > 0 ? (-r.top / range) : 0;
                    strengthProgress = Math.max(0, Math.min(1, strengthProgress));
                }
            }

            if (winW <= 1000 && pageX) {
                window.scrollTo(0, s);
                document.documentElement.scrollLeft = 0;
                document.body.scrollLeft = 0;
            }

            if (hdr) hdr.classList.toggle('solid', s > 60);

            if (s > last && s > 500 && !ovOpen) {
                if (hdr && isDesktop) hdr.style.transform = 'translateY(-100%)';
                if (inqFloat) inqFloat.classList.add('on');
                if (kakaoFloat) kakaoFloat.classList.add('on');
                if (totop) totop.classList.add('on');
            } else {
                if (hdr) hdr.style.transform = '';
                if (inqFloat) inqFloat.classList.remove('on');
                if (kakaoFloat) kakaoFloat.classList.remove('on');
                if (totop) totop.classList.remove('on');
            }
            last = s;

            if (!full) return;

            if (prog) prog.style.width = (d > 0 ? (s / d * 100) : 0) + '%';

            // PROJECT(works) - 스크롤 진행도에 따라 폭/모서리 변경
            if (wk && workProgress !== null) {
                wk.style.width = (88 + 12 * workProgress) + '%';
                var rad = 80 * (1 - workProgress);
                wk.style.borderRadius = rad + 'px ' + rad + 'px 0 0';
            }

            // STRENGTH - sticky 구간 진행도로 단계 전환
            if (st && strengthProgress !== null) {
                st.classList.toggle('step1', strengthProgress > 0.20 && strengthProgress <= 0.40);
                st.classList.toggle('step2', strengthProgress > 0.40 && strengthProgress <= 0.60);
                st.classList.toggle('step3', strengthProgress > 0.60 && strengthProgress <= 0.80);
                st.classList.toggle('step4', strengthProgress > 0.80);
                st.classList.toggle('swapped', strengthProgress > 0.20);

                // 배경 영상 베일: hero(투명에 가까움) -> strength 진입할수록 진해짐
                if (veil) {
                    // progress 0 => .25(은은하게), progress 1 => .82(텍스트 가독성 확보)
                    var v = 0.25 + strengthProgress * 0.57;
                    veil.style.opacity = v.toFixed(3);
                }
            }
        }

        function onScroll() {
            if (!ticking) {
                ticking = true;
                requestAnimationFrame(function () {
                    render(true);
                });
            }
        }

        window.addEventListener('scroll', onScroll, { passive: true });
        // 일부 모바일 환경에서 실제 스크롤이 window가 아닌 요소(body 등)에서 일어나도
        // 헤더 배경(.solid) 전환이 동작하도록 캡처 단계에서도 감지
        document.addEventListener('scroll', onScroll, { capture: true, passive: true });
        window.addEventListener('resize', onScroll, { passive: true });
        window.addEventListener('orientationchange', function () { setTimeout(function () { render(true); }, 200); });
        window.addEventListener('load', function () {
            requestAnimationFrame(function () {
                render(true);
                setTimeout(function () { render(true); }, 80);
            });
        });

        // 모바일: 주소창 접힘/펼침 등으로 실제 뷰포트 높이가 바뀔 때마다 재계산.
        // (이 재계산이 없어 "스크롤을 내렸다 올려야 정상 위치로 보이는" 문제가 있었음)
        if (window.visualViewport) {
            window.visualViewport.addEventListener('resize', onScroll, { passive: true });
            window.visualViewport.addEventListener('scroll', onScroll, { passive: true });
        }

        // 폰트/영상/이미지 로딩으로 레이아웃 확정이 늦어지는 경우 대비한 지연 재계산
        [150, 400, 900].forEach(function (t) { setTimeout(render, t); });

        render(); // 초기 1회 실행 (스크롤 안 해도 상태 잡힘)
    })();

    // reveal
    (function () {
        var io = new IntersectionObserver(function (es) {
            es.forEach(function (e) { e.target.classList.toggle('in', e.isIntersecting); });
        }, { threshold: .12, rootMargin: '0px 0px -8% 0px' });
        document.querySelectorAll('.reveal').forEach(function (el, i) {
            el.style.transitionDelay = (i % 4 * 60) + 'ms';
            io.observe(el);
        });
    })();

    // stats count-up (#stats 의 [data-count] 숫자가 화면에 들어오면 0 -> 목표값)
    (function () {
        var els = document.querySelectorAll('#stats [data-count]');
        if (!els.length) return;

        if (!('IntersectionObserver' in window)) {
            els.forEach(function (el) {
                el.textContent = (+el.dataset.count).toLocaleString();
            });
            return;
        }

        function countUp(el) {
            var target = +el.dataset.count;
            var dur = 1600;
            var start = performance.now();
            // 이전 카운트가 진행 중이면 취소
            if (el._raf) cancelAnimationFrame(el._raf);
