// ===== TWIN H FAQ Script =====
document.addEventListener('DOMContentLoaded', function () {

    var list = document.getElementById('faqList');
    if (!list) return;

    var items = Array.prototype.slice.call(list.querySelectorAll('.faq-item'));

    // 답변 높이 계산 후 열고/닫기
    function setOpen(item, open) {
        var a = item.querySelector('.faq-a');
        var q = item.querySelector('.faq-q');
        var inner = item.querySelector('.faq-a-inner');
        if (open) {
            item.classList.add('open');
            q.setAttribute('aria-expanded', 'true');
            a.style.maxHeight = inner.offsetHeight + 'px';
        } else {
            item.classList.remove('open');
            q.setAttribute('aria-expanded', 'false');
            a.style.maxHeight = '0px';
        }
    }

    // 클릭: 한 번에 하나만 열리는 아코디언(원하면 단순 toggle로 바꿔도 됨)
    items.forEach(function (item) {
        var q = item.querySelector('.faq-q');
        q.addEventListener('click', function () {
            var isOpen = item.classList.contains('open');
            items.forEach(function (other) {
                if (other !== item) setOpen(other, false);
            });
            setOpen(item, !isOpen);
        });
    });

    // 열린 항목 높이 재계산(리사이즈 시)
    window.addEventListener('resize', function () {
        items.forEach(function (item) {
            if (item.classList.contains('open')) {
                var a = item.querySelector('.faq-a');
                var inner = item.querySelector('.faq-a-inner');
                a.style.maxHeight = inner.offsetHeight + 'px';
            }
        });
    });

    // ===== 카테고리 필터 + 페이징(5개씩) + 번호 재정렬 =====
    var PER_PAGE = 5;
    var btns    = Array.prototype.slice.call(document.querySelectorAll('.ff-btn'));
    var pager   = document.getElementById('faqPager');
    var initBtn = document.querySelector('.ff-btn.on') || btns[0];
    var curCat  = initBtn ? initBtn.dataset.cat : 'all';
    var curPage = 1;

    function getFiltered() {
        return items.filter(function (it) {
            return curCat === 'all' || it.dataset.cat === curCat;
        });
    }

    function render() {
        var filtered = getFiltered();
        var totalPages = Math.max(1, Math.ceil(filtered.length / PER_PAGE));
        if (curPage > totalPages) curPage = totalPages;
        if (curPage < 1) curPage = 1;
        var start = (curPage - 1) * PER_PAGE;
        var end   = start + PER_PAGE;

        items.forEach(function (it) { it.classList.add('hide'); setOpen(it, false); });

        filtered.forEach(function (it, idx) {
            var noEl = it.querySelector('.q-no');
            if (noEl) noEl.textContent = ('0' + (idx + 1)).slice(-2);
            if (idx >= start && idx < end) it.classList.remove('hide');
        });

        renderPager(totalPages);
    }

    function makeBtn(label, page, opts) {
        opts = opts || {};
        var b = document.createElement('button');
        b.type = 'button';
        b.innerHTML = label;
        if (opts.on) b.classList.add('on');
        if (opts.disabled) { b.disabled = true; }
        else b.addEventListener('click', function () {
            curPage = page;
            render();
            var f = document.querySelector('.faq-filters');
            if (f) {
                var hdr = document.querySelector('header');
                var off = (hdr ? hdr.offsetHeight : 0) + 24;
                var y = f.getBoundingClientRect().top + window.pageYOffset - off;
                window.scrollTo({ top: y < 0 ? 0 : y, behavior: 'smooth' });
            }
        });
        return b;
    }

    function renderPager(totalPages) {
        if (!pager) return;
        pager.innerHTML = '';
        if (totalPages <= 1) return;

        // 480px \uc774\ud558\uc5d0\uc11c\ub9cc \ud55c \ubc88\uc5d0 5\uac1c\uc529 \ub178\ucd9c\ud558\ub294 \uc2ac\ub77c\uc774\ub529 \uc708\ub3c4\uc6b0 \uc801\uc6a9.
        // \uadf8 \uc678 \ud654\uba74\uc740 \uae30\uc874\ucc98\ub7fc \uc804\uccb4 \ud398\uc774\uc9c0 \ubc88\ud638\ub97c \ub178\ucd9c.
        var startPage = 1, endPage = totalPages;
        if (window.innerWidth <= 480) {
            var WINDOW = 5;
            var block = Math.floor((curPage - 1) / WINDOW);
            startPage = block * WINDOW + 1;
            endPage = Math.min(startPage + WINDOW - 1, totalPages);
        }

        pager.appendChild(makeBtn('\u2039', curPage - 1, { disabled: curPage === 1 }));
        for (var p = startPage; p <= endPage; p++) {
            pager.appendChild(makeBtn(String(p), p, { on: p === curPage }));
        }
        pager.appendChild(makeBtn('\u203a', curPage + 1, { disabled: curPage === totalPages }));
    }

    // 480px \uacbd\uacc4\ub97c \ub118\ub098\ub4e4 \ub54c \ud398\uc774\uc800 \ud45c\uc2dc \ubc29\uc2dd\uc774 \ubc14\ub00c\ubbc0\ub85c \ub2e4\uc2dc \ub80c\ub354
    var _lastNarrow = window.innerWidth <= 480;
    window.addEventListener('resize', function () {
        var n = window.innerWidth <= 480;
        if (n !== _lastNarrow) { _lastNarrow = n; render(); }
    });

    btns.forEach(function (btn) {
        btn.addEventListener('click', function () {
            btns.forEach(function (b) { b.classList.remove('on'); });
            btn.classList.add('on');
            curCat = btn.dataset.cat;
            curPage = 1;
            render();
        });
    });

    render();

});

document.addEventListener('DOMContentLoaded', function () {

    // 가치 마퀴 — "우리가 고객에게 제공하는 가치"
    (function () {
