            'Reliable Support for Stable Operations'
        ];
        var vh = '';
        for (var k = 0; k < 2; k++) {
            vals.forEach(function (t, i) {
                vh += '<span class="' + (i % 2 ? 'o' : '') + '">' + t + '</span>';
            });
        }
        vmq.innerHTML = vh;
    })();

    // 서비스 아코디언
    (function () {
        var items = document.querySelectorAll('.acc-item');
        if (!items.length) return;
        items.forEach(function (it) {
            var head = it.querySelector('.acc-head'),
                body = it.querySelector('.acc-body'),
                inner = it.querySelector('.acc-body-in');
            if (!head || !body || !inner) return;

            head.addEventListener('click', function () {
                var open = it.classList.contains('on');
                document.querySelectorAll('.acc-item.on').forEach(function (o) {
                    if (o !== it) {
                        o.classList.remove('on');
                        o.querySelector('.acc-body').style.height = '0px';
                    }
                });
                if (open) {
                    body.style.height = '0px';
                    it.classList.remove('on');
                } else {
                    body.style.height = inner.offsetHeight + 'px';
                    it.classList.add('on');
                }
            });
        });

        // 리사이즈 시 열린 아코디언 높이 재계산
        addEventListener('resize', function () {
            document.querySelectorAll('.acc-item.on').forEach(function (it) {
                var body = it.querySelector('.acc-body'),
                    inner = it.querySelector('.acc-body-in');
                if (body && inner) body.style.height = inner.offsetHeight + 'px';
            });
        });
    })();

    // 프로세스 섹션 — index.php의 #works(.proj)와 동일한 폭 확장 효과
    // + 앞 .prob 섹션이 콘텐츠 하단까지 보인 뒤 고정되도록 sticky top 동적 설정
    (function () {
        var sec = document.getElementById('flowsec');
        var prob = document.querySelector('.prob');
        if (!sec) return;

        var START = 88;   // 시작 너비(%)
        var RADIUS = 60;  // 시작 모서리 둥글기(px)
        var ticking = false;

        // .prob 콘텐츠가 화면보다 길면, 끝까지 스크롤된 뒤 하단에 맞춰 고정되도록
        // sticky top 을 (뷰포트높이 - 콘텐츠높이) 음수값으로 설정
        function setProbStickyTop() {
            if (!prob) return;
            if (window.innerWidth <= 768) { prob.style.top = ''; return; }
            var vh = window.innerHeight;
            var ph = prob.offsetHeight;
            var t = ph > vh ? (vh - ph) : 0;
            prob.style.top = t + 'px';
        }

        function render() {
            ticking = false;
            // 모바일에서는 폭 효과 비활성화
            if (window.innerWidth <= 768) {
                sec.style.width = '';
                sec.style.borderRadius = '';
                return;
            }
            var vh = window.innerHeight;
            var top = sec.getBoundingClientRect().top;
            var p = (vh - top) / (vh * 0.7);
            p = Math.max(0, Math.min(1, p));
            sec.style.width = (START + (100 - START) * p) + '%';
            var rad = RADIUS * (1 - p);
            sec.style.borderRadius = rad + 'px ' + rad + 'px 0 0';
        }

        function onScroll() {
            if (!ticking) {
                ticking = true;
                requestAnimationFrame(render);
            }
        }

        function onResize() {
            setProbStickyTop();
            onScroll();
        }

        setProbStickyTop();
        window.addEventListener('scroll', onScroll, { passive: true });
        window.addEventListener('resize', onResize, { passive: true });
        window.addEventListener('load', setProbStickyTop);
        render();
    })();

});

